#include <stdio.h>
#define MAXSIZE 40
typedef struct {
    int data[MAXSIZE];
    int top;
} SqStack;

void Push(SqStack *S, int x)
{
    S->data[++S->top] = x;
}

int Pop(SqStack *S)
{
    return S->data[S->top--];
}

int main(void)
{
    SqStack S;
    int n, d;
    S.top = -1;
    scanf("%d%d", &n, &d);
    do {
        Push(&S, n % d);
        n /= d;
    } while (n > 0);
    while (S.top != -1)
        putchar("0123456789ABCDEF"[Pop(&S)]);
    putchar('\n');
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
typedef struct SNode {
    int data;
    struct SNode *next;
} SNode;
SNode *Push(SNode *top, int x)
{
    SNode *s = (SNode *)malloc(sizeof(SNode));
    s->data = x;
    s->next = top;
    return s;
}

SNode *Pop(SNode *top, int *x)
{
    SNode *p = top->next;
    *x = top->data;
    free(top);
    return p;
}

int main(void)
{
    SNode *top = NULL;
    int x;
    while (scanf("%d", &x) == 1 && x != -1) {
        if (x > 0)
            top = Push(top, x);
        else if (top == NULL)
            printf("empty\n");
        else {
            top = Pop(top, &x);
            printf("%d\n", x);
        }
    }
    while (top != NULL)
        top = Pop(top, &x);
    return 0;
}

