#include <stdio.h>
#define MAXSIZE 100
typedef struct {
    int data[MAXSIZE];
    int top;
} SqStack;

void Push(SqStack *S, int x)
{
    S->data[++S->top] = x;
}

int Pop(SqStack *S)
{
    return S->data[S->top--];
}

int main(void)
{
    SqStack S;
    int c, a, b;
    S.top = -1;
    while ((c = getchar()) != '#' && c != EOF) {
        if (c >= '0' && c <= '9')
            Push(&S, c - '0');
        else if (c != ' ' && c != '\n') {
            a = Pop(&S);
            b = Pop(&S);
            if (c == '+') Push(&S, b + a);
            else if (c == '-') Push(&S, b - a);
            else if (c == '*') Push(&S, b * a);
            else Push(&S, b / a);
        }
    }
    printf("%d\n", Pop(&S));
    return 0;
}

#include <stdio.h>
int Pair(char l, char r)
{
    return (l == '(' && r == ')') ||
           (l == '[' && r == ']') ||
           (l == '{' && r == '}');
}

int main(void)
{
    char s[105], st[105];
    int top = -1, i, ok = 1;
    if (fgets(s, sizeof(s), stdin) == NULL)
        s[0] = '\0';
    for (i = 0; s[i] != '\0' && ok; i++) {
        switch (s[i]) {
        case '(': case '[': case '{':
            st[++top] = s[i];
            break;
        case ')': case ']': case '}':
            if (top == -1 || !Pair(st[top], s[i]))
                ok = 0;
            else
                top--;
            break;
        }
    }
